const f = $input.first().json;
const phrases = String(f["Frazy"] || "").split(/\r?\n/).map(s => s.trim()).filter(Boolean).slice(0, 5);
const categories = String(f["Kategorie"] || "").split(/[,\s]+/).map(s => s.trim()).filter(Boolean).slice(0, 5);
const max = Math.min(20, Math.max(1, parseInt(f["Max wynikow na fraze"], 10) || 5));
if (!phrases.length) { throw new Error("Brak fraz wyszukiwania (pole Frazy)."); }
return phrases.map(query => ({ json: { query, categories, max } }));

const params = $("Przygotuj zapytania").all().map(i => i.json);
const responses = $input.all().map(i => i.json);
const rowRe = /^\|\s*(\S+)\s*\|\s*(\S+)\s*\|\s*(.*?)\s*\|\s*(.*)\s*\|\s*(\S+)\s*\|$/;
const seen = new Map();
let failed = 0, empty = 0;
const sections = params.map((p, i) => {
  const r = responses[i] || {};
  if (r.error || r.status === "Blocker" || (r.exit_code !== undefined && r.exit_code !== 0)) {
    failed++;
    return "### " + p.query + "

Blad wyszukiwania: " + String(r.error ? (r.error.message || r.error) : (r.stderr || "brak odpowiedzi")).slice(0, 300) + "
";
  }
  const rows = String(r.stdout || "").split("
").map(l => l.trim()).filter(l => rowRe.test(l) && !l.startsWith("| ArXiv ID") && !l.startsWith("|---")).map(l => l.match(rowRe));
  if (!rows.length) { empty++; return "### " + p.query + "

Brak wynikow.
"; }
  const lines = rows.map(m => {
    const id = m[1].replace(/v\d+$/, "");
    if (!seen.has(id)) seen.set(id, { id, date: m[2], authors: m[3], title: m[4], url: m[5], phrases: [p.query] });
    else seen.get(id).phrases.push(p.query);
    return "| " + id + " | " + m[2] + " | " + m[3] + " | " + m[4] + " | " + m[5] + " |";
  });
  return "### " + p.query + "

| ArXiv ID | Data | Autorzy | Tytul | URL |
|---|---|---|---|---|
" + lines.join("
") + "
";
});
const status = failed === params.length ? "Blocker" : (failed || empty ? "Warning" : "OK");
const ts = new Date().toISOString();
const cats = params[0].categories.length ? params[0].categories.join(", ") : "wszystkie";
const report = "# Przeglad literatury arXiv

- Data (UTC): " + ts + "
- Status roboczy: **" + status + "**
- Kategorie: " + cats + "
- Maks. wynikow na fraze: " + params[0].max + "
- Liczba fraz: " + params.length + "
- Unikalnych publikacji: " + seen.size + "

## Wyniki dla fraz

" + sections.join("
") + "
## Uwagi

- Zrodlo: arXiv (preprinty, brak recenzji); poziom zaufania nizszy niz peer-reviewed.
- Zestawienie wynikow wyszukiwania, bez oceny merytorycznej; selekcja nalezy do czlowieka.
- Wpisy do Cross-Reference-Log-LTR wymagaja weryfikacji i zgody wlasciciela badania.
";
const fname = "arxiv-" + ts.replace(/[:.]/g, "-") + ".md";
const bin = await this.helpers.prepareBinaryData(Buffer.from(report, "utf8"), fname, "text/markdown");
const pubs = Array.from(seen.values());
return [{ json: { status, unique: seen.size, failed, empty, fname, pubs }, binary: { data: bin } }];

const src = $("Raport literatury").first().json;
const f = $input.first().json;
const chosen = [].concat(f["Publikacje"] || []).map(String);
const ids = chosen.map(s => s.split(" | ")[0].trim());
const sel = src.pubs.filter(p => ids.includes(p.id));
const ts = new Date().toISOString();
const topic = String(f["Temat badania"] || "").trim();
const out = { generated_utc: ts, topic, source: "arXiv (preprinty, brak recenzji)", status: "do_weryfikacji", report_file: src.fname, selected: sel };
const fname = "arxiv-wybor-" + ts.replace(/[:.]/g, "-") + ".json";
const bin = await this.helpers.prepareBinaryData(Buffer.from(JSON.stringify(out, null, 2), "utf8"), fname, "application/json");
const topicOk = /^[A-Za-z0-9][A-Za-z0-9._-]{0,80}$/.test(topic);
const doLog = topicOk && sel.length >= 1 && sel.length <= 20;
const logNote = doLog ? "" : (!topicOk ? " Log badania pominiety: brak lub niepoprawny temat." : " Log badania pominiety: wybierz od 1 do 20 pozycji.");
const logBody = doLog ? { topic, publications: sel.map(p => ({ id: p.id, title: p.title, authors: p.authors, date: p.date, url: p.url })) } : null;
return [{ json: { fname, count: sel.length, topic, doLog, logNote, logBody }, binary: { data: bin } }];

const pubs = $("Raport literatury").first().json.pubs;
const fields = [
  { fieldLabel: "Publikacje", fieldType: "checkbox", fieldOptions: { values: pubs.map(p => ({ option: p.id + " | " + p.title.slice(0, 110) + " | " + p.date.slice(0, 4) })) } },
  { fieldLabel: "Temat badania", fieldType: "text", placeholder: "np. T04-GR-PPN-Yukawa-Perihelion" }
];
return [{ json: { fields: JSON.stringify(fields) } }];
